export const OWN_PLANILLA_DEPARTMENTS_SOURCE_PINS=Object.freeze(Object.fromEntries(Object.entries(rows).map(([file,row])=>[file,Object.freeze({before:row.beforeSha256,after:row.afterSha256,beforeBytes:row.beforeBytes,afterBytes:row.afterBytes})])));
export function projectPlanillaDepartmentsRawSourceToParent(file,value){
 assert.equal(typeof file,'string');assert.ok(Buffer.isBuffer(value));
 if(!Object.hasOwn(rows,file))return value;const row=rows[file];
 assert.equal(value.length,row.afterBytes,'PLANILLA_DEPARTMENTS_CURRENT_SOURCE_BYTES:'+file);assert.equal(hash(value),row.afterSha256,'PLANILLA_DEPARTMENTS_CURRENT_SOURCE_SHA:'+file);
 let parent=value;for(const op of [...row.spans].reverse()){
  const after=Buffer.from(op.after),before=Buffer.from(op.before);
  assert.equal(parent.indexOf(after),op.afterOffset,'PLANILLA_DEPARTMENTS_EXACT_SPAN_POSITION:'+file);assert.equal(parent.indexOf(after,op.afterOffset+after.length),-1,'PLANILLA_DEPARTMENTS_UNIQUE_SPAN:'+file);
  assert.deepEqual(parent.subarray(op.afterOffset,op.afterOffset+after.length),after,'PLANILLA_DEPARTMENTS_COMPLETE_SPAN:'+file);
  parent=Buffer.concat([parent.subarray(0,op.afterOffset),before,parent.subarray(op.afterOffset+after.length)]);
 }
 assert.equal(parent.length,row.beforeBytes,'PLANILLA_DEPARTMENTS_PARENT_BYTES:'+file);assert.equal(hash(parent),row.beforeSha256,'PLANILLA_DEPARTMENTS_COMPLETE_PARENT_SHA:'+file);return parent;
}
